  IF NOT (OLD.nombre <=> NEW.nombre) THEN
    INSERT INTO log_cambios (tabla, id_registro, campo, valor_anterior, valor_nuevo)
    VALUES ('alumnos', NEW.id, 'nombre', OLD.nombre, NEW.nombre);
  END IF;
  IF NOT (OLD.email <=> NEW.email) THEN
    INSERT INTO log_cambios (tabla, id_registro, campo, valor_anterior, valor_nuevo)
    VALUES ('alumnos', NEW.id, 'email', OLD.email, NEW.email);
  END IF;
  IF NOT (OLD.telefono <=> NEW.telefono) THEN
    INSERT INTO log_cambios (tabla, id_registro, campo, valor_anterior, valor_nuevo)
    VALUES ('alumnos', NEW.id, 'telefono', OLD.telefono, NEW.telefono);
  END IF;
END //

DELIMITER ;
```

Cada campo se verifica por separado. Solo se genera un registro si ese campo específico cambió.

