  IF v_activo = FALSE THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El alumno está inactivo';
  END IF;

  SELECT COUNT(*) INTO v_existe FROM asignaturas WHERE id = p_id_asignatura;
  IF v_existe = 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'La asignatura no existe';
  END IF;

  SELECT COUNT(*) INTO v_existe FROM matriculas
  WHERE id_alumno = p_id_alumno AND id_asignatura = p_id_asignatura;
  IF v_existe > 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Ya está matriculado';
  END IF;

  INSERT INTO matriculas (id_alumno, id_asignatura, fecha_matricula, estado)
  VALUES (p_id_alumno, p_id_asignatura, CURDATE(), 'activa');

  SELECT CONCAT('Alumno ', p_id_alumno, ' matriculado en asignatura ', p_id_asignatura) AS resultado;
END //
DELIMITER ;

